      refs.toast.classList.add('show');
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => refs.toast.classList.remove('show'), 2200);
    }

    // ── 模式 ──
    function syncModeBadge() {
      const label = MODE_NAMES[currentMode];
      const next = MODE_NAMES[MODES[(MODES.indexOf(currentMode) + 1) % MODES.length]];
      refs.modeLabel.textContent = label;
      refs.modeBadge.title = `${label} → ${next}`;
      refs.modeBadge.setAttribute('aria-label', `切换发送模式，当前：${label}`);
      refs.modeDots.querySelectorAll('.mode-dot').forEach(dot => {
        dot.classList.toggle('active', dot.dataset.mode === currentMode);
      });
    }

    function toggleMode(e) {
      e.stopPropagation();
      const idx = (MODES.indexOf(currentMode) + 1) % MODES.length;
      currentMode = MODES[idx];
      try { localStorage.setItem(MODE_KEY, currentMode); } catch {}
      syncModeBadge();
    }

    refs.modeBadge.addEventListener('click', toggleMode);

    // ── 折叠 ──
    function setExpandedUI(expanded) {
      const label = expanded ? '折叠选项' : '展开选项';
      const title = expanded ? '折叠' : '展开';
      [refs.toolbarToggle, refs.btnCollapse].forEach(btn => {
        btn.setAttribute('aria-expanded', String(expanded));
        btn.setAttribute('aria-label', label);
        btn.title = title;
      });
    }

    function toggleCollapse(e) {
      e && e.stopPropagation();
      closeThemePanel();
      collapsed = !collapsed;
      refs.card.classList.toggle('collapsed', collapsed);
      setExpandedUI(!collapsed);
    }

    refs.toolbarToggle.addEventListener('click', toggleCollapse);
    refs.btnCollapse.addEventListener('click', toggleCollapse);

    // ── Slash 转义 ──
    function escapeSlashArg(text) {
      return String(text)
        .replace(/\r\n|\r|\n/g, ' ')
        .replace(/\|/g, '｜')
        .replace(/\s+/g, ' ')
        .trim();
    }

    // ── 宿主输入框 ──
    function readParentInput() {
      try {
        const $ = window.parent && window.parent.$;
        if (typeof $ === 'function') {
          const val = $('#send_textarea').val();
          if (typeof val === 'string') return { ok: true, value: val };
        }
        const el = window.parent?.document?.getElementById('send_textarea')
          || window.parent?.document?.querySelector?.('#send_textarea, textarea');
        if (el && typeof el.value === 'string') return { ok: true, value: el.value };
      } catch {}
      return { ok: false, value: '' };
    }

    function dispatchOption(text) {
      const safe = escapeSlashArg(text);
      if (!safe) return;

      if (typeof triggerSlash !== 'function') {
        showToast(`已模拟（无宿主）: ${safe.slice(0, 40)}${safe.length > 40 ? '…' : ''}`);
        return;
      }
      if (currentMode === 'send') {
        triggerSlash(`/send ${safe}|/trigger`);
      } else if (currentMode === 'setinput') {
        triggerSlash(`/setinput ${safe}`);
      } else {
        const { ok, value: cur } = readParentInput();
        if (!ok) {
          showToast('无法读取输入框，已仅填入当前选项');
          triggerSlash(`/setinput ${safe}`);
        } else {
          const parts = [cur, text].map(escapeSlashArg).filter(Boolean);
          triggerSlash(`/setinput ${parts.join('\n')}`);
        }
      }
    }

    // ── 发送 ──
    refs.optionsGrid.addEventListener('click', e => {
      const item = e.target.closest('.option-item');
      if (!item || item.disabled) return;
      const text = item.textContent.trim();
      if (!text || ['…', '...'].includes(text)) return;

      dispatchOption(text);

      if (currentMode !== 'append') {
        item.classList.add('picked');
        clearTimeout(pickTimer);
        clearTimeout(pickClearTimer);
        pickTimer = setTimeout(() => {
          if (!collapsed) toggleCollapse();
          pickClearTimer = setTimeout(() => item.classList.remove('picked'), 400);
        }, 280);
      }
    });

    // ── 渲染 ──
    function setCount(n) {
      refs.countBadge.textContent = n > 0 ? String(n) : '';
      refs.countBadge.title = n > 0 ? `共 ${n} 个选项` : '';
    }

    function renderSkeleton() {
      refs.optionsGrid.replaceChildren();
      setCount(0);
      for (let i = 0; i < 4; i++) {
        const el = document.createElement('div');
        el.className = 'skeleton-item';
        el.setAttribute('aria-hidden', 'true');
        refs.optionsGrid.appendChild(el);
      }
    }

    function renderError(err) {
      refs.optionsGrid.replaceChildren();
      setCount(0);
      const el = document.createElement('div');
      el.className = 'error';
      el.textContent = `加载失败: ${String(err.message || err)}`;
      refs.optionsGrid.appendChild(el);
    }

    function renderOptions(opts) {
      refs.optionsGrid.replaceChildren();
      setCount(opts.length);

      if (!opts.length) {
        const empty = document.createElement('div');
        empty.className = 'empty';
        empty.textContent = '暂无可选回复';
        refs.optionsGrid.appendChild(empty);
        return;
      }

      opts.forEach((opt, i) => {
        const el = document.createElement('button');
        el.type = 'button';
        el.className = 'option-item';
        el.textContent = opt;
        el.title = opt;
        el.style.animationDelay = `${Math.min(i, 12) * 0.04}s`;
        if (opt.length > 20) el.style.fontSize = '0.9rem';
        refs.optionsGrid.appendChild(el);
      });
    }

    // ── 初始化 ──
    buildThemePanel();
    renderSkeleton();

    setTimeout(() => {
      try {
        const theme = localStorage.getItem(THEME_KEY) || 'paper';
        applyTheme(theme);
        const savedMode = localStorage.getItem(MODE_KEY) || 'send';
        currentMode = MODES.includes(savedMode) ? savedMode : 'send';
        syncModeBadge();
      } catch {
        applyTheme('paper');
        syncModeBadge();
      }

      try {
        const msg = getChatMessages(getCurrentMessageId())[0];
        const match = msg.message.match(/<options>((?:(?!<options>).)*?)<\/options>/s);
        const opts = (match ? match[1] : '').split('|').map(s => s.trim()).filter(Boolean);
        renderOptions(opts);
      } catch (err) {
        renderError(err);
      }
    }, 0);
  </script>
</body>
</html>

